//! OP_CONVERT target 6 (svg, #192 gap 3): byte-identity against the Ruby
//! goldens generated by `Converters::FormatConverter` (`/tmp` goldens from
//! the corpus fonts when present — the durable cross-tier proof lives in the
//! fontisan parity cells, which run the Ruby tier at test time).
mod common;

use common::corpus;

fn engine_svg(font: &[u8]) -> Result<Vec<u8>, String> {
    let (status, payload_or_error) = engine_svg_raw(font);
    assert_eq!(status, fontisan::ffi::FontisanStatus::Ok as i32, "{payload_or_error}");
    Ok(payload_or_error.into_bytes())
}

/// The raw ConvertFailed message (`<ruby class>: <message>`).
fn engine_svg_raw(font: &[u8]) -> (i32, String) {
    let target = 6u32; // Target::Svg
    let mut input = target.to_be_bytes().to_vec();
    input.extend_from_slice(&0u32.to_be_bytes()); // source hint
    input.extend_from_slice(&0i64.to_be_bytes()); // timestamp
    input.extend_from_slice(font);
    let req = fontisan::ffi::FontisanRequest {
        header: fontisan::ffi::FontisanHeader::current::<fontisan::ffi::FontisanRequest>(),
        op: fontisan::ffi::OP_CONVERT,
        flags: 0,
        input: input.as_ptr(),
        input_len: input.len(),
    };
    let mut out = std::ptr::null_mut();
    let status = unsafe { fontisan::ffi::fontisan_call(&req, &mut out) };
    let text = unsafe { out.as_ref() }
        .map(|r| {
            if status == fontisan::ffi::FontisanStatus::Ok as i32 {
                String::from_utf8(
                    unsafe { std::slice::from_raw_parts(r.payload, r.payload_len) }.to_vec(),
                )
                .unwrap()
            } else {
                String::from_utf8(
                    unsafe { std::slice::from_raw_parts(r.error.message, r.error.message_len) }
                        .to_vec(),
                )
                .unwrap()
            }
        })
        .unwrap_or_default();
    unsafe { fontisan::ffi::fontisan_result_free(out) };
    (status, text)
}

fn corpus_font(name: &str) -> Option<Vec<u8>> {
    std::fs::read(corpus()?.join("fonts").join(name)).ok()
}

#[test]
fn matches_the_ruby_goldens() {
    let cases = [
        ("NotoSans-Regular.ttf", "/tmp/golden-notosans.svg"),
        (
            "NotoSansJP-Regular.otf",
            "/tmp/golden-NotoSansJP-Regular.otf.svg",
        ),
        (
            "SourceSans3-Regular.otf.woff",
            "/tmp/golden-SourceSans3-Regular.otf.woff.svg",
        ),
        ("SourceSans3-Regular.otf", "/tmp/g2-SourceSans3-Regular.otf.svg"),
        ("SourceSans3-Regular.ttf", "/tmp/g2-SourceSans3-Regular.ttf.svg"),
        (
            "SourceSans3-Regular.ttf.woff2",
            "/tmp/g2-SourceSans3-Regular.ttf.woff2.svg",
        ),
        (
            "MonaSansVF[wdth,wght,opsz,ital].ttf",
            "/tmp/g2-MonaSansVF_wdth_wght_opsz_ital_.ttf.svg",
        ),
        ("NotoSans[wdth,wght].ttf", "/tmp/g2-NotoSans_wdth_wght_.ttf.svg"),
        ("TestTTF.ttf", "/tmp/g2-fonttools_test_ttf.svg"),
        ("TestOTF.otf", "/tmp/g2-fonttools_test_otf.svg"),
        ("SourceSans3VF-Italic.ttf", "/tmp/g2-ss3vf_italic.svg"),
        ("SourceSans3VF-Upright.otf", "/tmp/g2-ss3vf_upright_otf.svg"),
    ];
    let mut checked = 0;
    for (font_name, golden_path) in cases {
        let Some(font) = corpus_font(font_name) else { continue };
        let Ok(golden) = std::fs::read(golden_path) else { continue };
        let got = engine_svg(&font).unwrap_or_else(|e| panic!("{font_name}: {e}"));
        if got != golden {
            for (i, (a, b)) in got.iter().zip(golden.iter()).enumerate() {
                if a != b {
                    let lo = i.saturating_sub(80);
                    panic!(
                        "{font_name}: first diff at byte {i}\nengine: {}\nruby:   {}",
                        String::from_utf8_lossy(&got[lo..(i + 80).min(got.len())]),
                        String::from_utf8_lossy(&golden[lo..(i + 80).min(golden.len())])
                    );
                }
            }
            panic!(
                "{font_name}: length {} vs golden {}",
                got.len(),
                golden.len()
            );
        }
        checked += 1;
    }
    assert!(
        std::env::var_os("FONTISAN_SPIKE_REQUIRE_CORPUS").is_some() || checked > 0,
        "no goldens to compare"
    );
}

#[test]
fn cff2_variable_fonts_raise_the_instancing_error() {
    let Some(font) = corpus_font("SourceSans3VF-Upright.otf") else {
        return;
    };
    let (status, message) = engine_svg_raw(&font);
    assert_eq!(status, fontisan::ffi::FontisanStatus::ConvertFailed as i32);
    assert!(
        message.ends_with(
            "Static instancing needs TrueType outlines with gvar \
             (CFF2 variable fonts are not supported yet)"
        ),
        "{message}"
    );
}
